mapper.select:
SELECT o.assignee_id AS assigneeId, SUM(CASE WHEN o.status IN ('ASSIGNED', 'ACCEPTED', 'ARRIVED') THEN 1 ELSE 0 END) AS handCount, SUM(CASE WHEN o.status IN ('FINISHED', 'CONFIRMED', 'CLOSED') AND o.finish_time >= #{dayBegin} THEN 1 ELSE 0 END) AS todayFinishCount FROM t_work_order o WHERE o.deleted = 0 AND o.assignee_id IN
#{id}
GROUP BY o.assignee_id
